// The nine shipped Game-flow tiles: six style thumbnails and three template cards.
//
// The Game flow's Look step renders one tile per `GAME_STYLE_PRESETS` entry and
// its Design step one card per shipped Godot template. Both sets are drawn here
// rather than generated by a model, so they cost nothing to ship, never drift
// from the preset list, and reproduce byte for byte.
//
// Style tiles are 256x144 and follow game-prd.md § 6.2: a sky band, a ground
// band and one blocky figure, drawn on a small canvas and upscaled with
// nearest-neighbour so the pixel grid stays hard. The cell size is the preset's
// own scale read the way the descriptors mean it — a preset whose sprites are
// 16px cells shows chunkier blocks on a fixed tile than one at 32px, so
// `pixel-8bit` draws 16x9 at 16x and the rest 32x18 at 8x. `painted-2d` has no
// grid: it renders at full size and is box-blurred.
//
// Template cards are 512x288 (§ 6.3), drawn at 4x from a 128x72 canvas. Their
// palettes are sampled from each template's own placeholder assets under
// packages/godot-templates/templates/<template>/assets/, so replacing that art
// moves the cards with it. The placeholders themselves are diagonal-stripe
// backgrounds and colour-swatch grids with no readable subject, so each card
// draws the loop as a schematic — a platform silhouette, a walled room, a
// vertical scroller — in the sampled colours.
//
// PNGs are written by the encoder below rather than by an image library: no
// timestamp chunk, one deflate level, same bytes on every machine with the same
// zlib. `sharp` is used only to read the placeholder pixels.
//
// Usage:
//   node scripts/make-game-style-tiles.mjs           # write all nine
//   node scripts/make-game-style-tiles.mjs --check    # fail on drift, write nothing
//
// Also wired as `npm run gen:game-tiles` / `gen:game-tiles:check`.

import { readFile, writeFile, mkdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { deflateSync } from "node:zlib";
import sharp from "sharp";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const STYLES_DIR = path.join(
  ROOT,
  "packages/base-nodes/nodetool/assets/nodetool-base/styles"
);
const TEMPLATE_CARD_DIR = path.join(
  ROOT,
  "packages/base-nodes/nodetool/assets/nodetool-base/templates"
);
const TEMPLATES_DIR = path.join(ROOT, "packages/godot-templates/templates");

const TILE_WIDTH = 256;
const TILE_HEIGHT = 144;
const CARD_WIDTH = 512;
const CARD_HEIGHT = 288;
const CARD_SCALE = 4;

// ---------------------------------------------------------------- PNG output

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    table[n] = c;
  }
  return table;
})();

function crc32(buffer) {
  let c = -1;
  for (let i = 0; i < buffer.length; i++) {
    c = CRC_TABLE[(c ^ buffer[i]) & 0xff] ^ (c >>> 8);
  }
  return (c ^ -1) >>> 0;
}

function pngChunk(type, data) {
  const head = Buffer.alloc(4);
  head.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([head, body, crc]);
}

/** 8-bit truecolour PNG, filter 0 on every row, no ancillary chunks. */
function encodePng(width, height, pixels) {
  const stride = width * 3;
  const raw = Buffer.alloc(height * (stride + 1));
  for (let y = 0; y < height; y++) {
    const at = y * (stride + 1);
    raw[at] = 0;
    Buffer.from(pixels.buffer, pixels.byteOffset + y * stride, stride).copy(raw, at + 1);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: truecolour
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    pngChunk("IHDR", ihdr),
    pngChunk("IDAT", deflateSync(raw, { level: 9 })),
    pngChunk("IEND", Buffer.alloc(0))
  ]);
}

// ------------------------------------------------------------------- colours

function rgb(hex) {
  const n = Number.parseInt(hex.slice(1), 16);
  return [(n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff];
}

function scaleColor(color, factor) {
  return color.map((v) => Math.max(0, Math.min(255, Math.round(v * factor))));
}

function mixColor(a, b, t) {
  return a.map((v, i) => Math.round(v + (b[i] - v) * t));
}

// -------------------------------------------------------------------- canvas

class Canvas {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.data = new Uint8Array(width * height * 3);
  }

  set(x, y, color) {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) {
      return;
    }
    const at = (y * this.width + x) * 3;
    this.data[at] = color[0];
    this.data[at + 1] = color[1];
    this.data[at + 2] = color[2];
  }

  get(x, y) {
    const at = (y * this.width + x) * 3;
    return [this.data[at], this.data[at + 1], this.data[at + 2]];
  }

  fill(x, y, width, height, color) {
    for (let dy = 0; dy < height; dy++) {
      for (let dx = 0; dx < width; dx++) {
        this.set(x + dx, y + dy, color);
      }
    }
  }

  row(y, color) {
    this.fill(0, y, this.width, 1, color);
  }
}

function upscale(canvas, factor) {
  const out = new Canvas(canvas.width * factor, canvas.height * factor);
  for (let y = 0; y < canvas.height; y++) {
    for (let x = 0; x < canvas.width; x++) {
      out.fill(x * factor, y * factor, factor, factor, canvas.get(x, y));
    }
  }
  return out;
}

function boxBlur(canvas, radius, passes) {
  let source = canvas.data;
  for (let pass = 0; pass < passes; pass++) {
    const target = new Uint8Array(source.length);
    for (let y = 0; y < canvas.height; y++) {
      for (let x = 0; x < canvas.width; x++) {
        const sum = [0, 0, 0];
        let count = 0;
        for (let dy = -radius; dy <= radius; dy++) {
          for (let dx = -radius; dx <= radius; dx++) {
            const sx = Math.min(canvas.width - 1, Math.max(0, x + dx));
            const sy = Math.min(canvas.height - 1, Math.max(0, y + dy));
            const at = (sy * canvas.width + sx) * 3;
            sum[0] += source[at];
            sum[1] += source[at + 1];
            sum[2] += source[at + 2];
            count++;
          }
        }
        const at = (y * canvas.width + x) * 3;
        target[at] = Math.round(sum[0] / count);
        target[at + 1] = Math.round(sum[1] / count);
        target[at + 2] = Math.round(sum[2] / count);
      }
    }
    source = target;
  }
  canvas.data = source;
  return canvas;
}

// -------------------------------------------------------------------- sprites

/**
 * Sprites are ASCII so a shape edit stays readable in the diff.
 * `O` outline, `K` skin, `E` eye, `B` body, `A` accent, `.` leave the ground
 * or sky showing through.
 */
const FIGURE_LARGE = [
  "..OOOO..",
  ".OKKKKO.",
  ".OKEKEO.",
  ".OKKKKO.",
  "..OBBO..",
  ".OBBBBO.",
  "AOBBBBOA",
  ".OBBBBO.",
  ".OB..BO.",
  ".OO..OO."
];

const FIGURE_SMALL = [".OOO.", "OKEKO", ".OBO.", "OBBBO", ".O.O."];

const FIGURE_TOPDOWN = [
  ".OOOO.",
  "OKKKKO",
  "OKEEKO",
  "OBBBBO",
  "OBBBBO",
  ".OOOO."
];

const SHIP = [
  "...O...",
  "..OBO..",
  "..OBO..",
  ".OBKBO.",
  "OBBBBBO",
  "O.OBO.O",
  "...A..."
];

const DRONE = [".OOO.", "OBBBO", "OBEBO", ".O.O."];

function drawSprite(canvas, sprite, x, y, palette, scale = 1, rim = null) {
  for (let row = 0; row < sprite.length; row++) {
    const line = sprite[row];
    let rimAt = -1;
    if (rim) {
      rimAt = line.lastIndexOf("O");
    }
    for (let col = 0; col < line.length; col++) {
      const ch = line[col];
      if (ch === ".") {
        continue;
      }
      const color = ch === "O" && col === rimAt ? rim : palette[ch];
      if (!color) {
        continue;
      }
      canvas.fill(x + col * scale, y + row * scale, scale, scale, color);
    }
  }
}

// -------------------------------------------------------------- style presets

/**
 * One entry per `GAME_STYLE_PRESETS` id, with the palette read off that
 * preset's descriptor gist in game-prd.md § 5.6. `cell` is the output pixels
 * one art cell covers, and divides both 256 and 144.
 */
const STYLE_TILES = [
  {
    id: "pixel-16bit",
    cell: 8,
    sky: ["#f2a65a", "#e07a4f"],
    ground: ["#c98f57", "#a97244", "#8a5c34", "#6f4a2a"],
    palette: { O: "#14100e", K: "#f2c8a0", E: "#14100e", B: "#c0392b", A: "#8e2b20" }
  },
  {
    id: "pixel-8bit",
    cell: 16,
    sky: ["#0000fc", "#0058f8"],
    ground: ["#00a800", "#a84400", "#503000"],
    palette: { O: "#000000", K: "#fcbcb0", E: "#000000", B: "#fc0000", A: "#fc0000" }
  },
  {
    id: "pixel-handheld",
    cell: 8,
    sky: ["#f0f4d8", "#d6e2b4"],
    ground: ["#c2d49a", "#8aa471", "#5f7a55", "#3c5040"],
    palette: { O: "#2f4034", K: "#f0f4d8", E: "#2f4034", B: "#7c9868", A: "#5f7a55" }
  },
  {
    id: "pixel-1bit",
    cell: 8,
    sky: ["#e6e2d3", "#e6e2d3"],
    ground: ["#1a1a22", "#1a1a22", "#1a1a22", "#1a1a22"],
    dither: true,
    palette: { O: "#1a1a22", K: "#e6e2d3", E: "#1a1a22", B: "#e6e2d3", A: "#1a1a22" }
  },
  {
    id: "pixel-modern",
    cell: 8,
    sky: ["#5b3f8f", "#a8577e"],
    ground: ["#3f7f6b", "#2f6255", "#254c46", "#1c3a37"],
    dither: true,
    rim: "#7fe3ff",
    palette: { O: "#2a1b3d", K: "#f6d2a8", E: "#2a1b3d", B: "#e2703a", A: "#b84f2c" }
  },
  {
    id: "painted-2d",
    painted: true,
    sky: ["#8fb8e8", "#e7c9a0"],
    ground: ["#7fa05a", "#41603a"],
    palette: { O: "#8a4436", K: "#efc9a2", E: "#6d3226", B: "#c25a4a", A: "#a3453a" }
  }
];

function spritePalette(entry) {
  return Object.fromEntries(
    Object.entries(entry.palette).map(([key, hex]) => [key, rgb(hex)])
  );
}

function drawStyleTile(entry) {
  if (entry.painted) {
    return drawPaintedTile(entry);
  }
  const width = TILE_WIDTH / entry.cell;
  const height = TILE_HEIGHT / entry.cell;
  const canvas = new Canvas(width, height);
  const horizon = Math.round(height * 0.62);
  const sky = entry.sky.map(rgb);
  const ground = entry.ground.map(rgb);

  for (let y = 0; y < horizon; y++) {
    canvas.row(y, mixColor(sky[0], sky[1], horizon < 2 ? 0 : y / (horizon - 1)));
  }
  for (let y = horizon; y < height; y++) {
    canvas.row(y, ground[Math.min(y - horizon, ground.length - 1)]);
  }
  if (entry.dither) {
    const light = entry.id === "pixel-1bit" ? rgb(entry.sky[0]) : ground[0];
    const dark = ground[Math.min(1, ground.length - 1)];
    for (let x = 0; x < width; x++) {
      canvas.set(x, horizon, x % 2 === 0 ? light : dark);
      canvas.set(x, horizon + 1, x % 4 === 0 ? light : dark);
    }
  }

  const sprite = width <= 16 ? FIGURE_SMALL : FIGURE_LARGE;
  const palette = spritePalette(entry);
  drawSprite(
    canvas,
    sprite,
    Math.round(width * 0.28) - Math.floor(sprite[0].length / 2),
    horizon - sprite.length,
    palette,
    1,
    entry.rim ? rgb(entry.rim) : null
  );
  return upscale(canvas, entry.cell);
}

function drawPaintedTile(entry) {
  const canvas = new Canvas(TILE_WIDTH, TILE_HEIGHT);
  const horizon = Math.round(TILE_HEIGHT * 0.62);
  const sky = entry.sky.map(rgb);
  const ground = entry.ground.map(rgb);
  for (let y = 0; y < horizon; y++) {
    canvas.row(y, mixColor(sky[0], sky[1], y / (horizon - 1)));
  }
  for (let y = horizon; y < TILE_HEIGHT; y++) {
    canvas.row(
      y,
      mixColor(ground[0], ground[1], (y - horizon) / (TILE_HEIGHT - horizon - 1))
    );
  }
  const scale = 8;
  const palette = spritePalette(entry);
  drawSprite(
    canvas,
    FIGURE_LARGE,
    Math.round(TILE_WIDTH * 0.28) - (FIGURE_LARGE[0].length * scale) / 2,
    horizon - FIGURE_LARGE.length * scale,
    palette,
    scale
  );
  return boxBlur(canvas, 3, 2);
}

// ------------------------------------------------------------ template cards

/**
 * The pixels each card's palette is sampled from. Coordinates are inside a
 * placeholder cell rather than on its border, so a swatch grid reads as a
 * colour and not as the gap between two.
 */
const TEMPLATE_CARDS = [
  {
    template: "platformer",
    samples: {
      sky: ["assets/images/bg_far.png", 10, 10],
      tile: ["assets/tiles/tiles_ground.png", 8, 8],
      accent: ["assets/tiles/tiles_ground.png", 40, 8],
      player: ["assets/sprites/player.png", 16, 16],
      enemy: ["assets/sprites/enemy_walker.png", 16, 16]
    },
    draw: drawPlatformerCard
  },
  {
    template: "topdown",
    samples: {
      floor: ["assets/tiles/tiles_floor.png", 8, 8],
      wall: ["assets/tiles/tiles_floor.png", 56, 8],
      player: ["assets/sprites/player.png", 16, 16],
      enemy: ["assets/sprites/enemy_chaser.png", 16, 16]
    },
    draw: drawTopdownCard
  },
  {
    template: "shmup",
    samples: {
      sky: ["assets/images/bg_space.png", 10, 10],
      player: ["assets/sprites/player.png", 16, 16],
      enemy: ["assets/sprites/enemy_drone.png", 16, 16]
    },
    draw: drawShmupCard
  }
];

const INK = rgb("#101820");

async function samplePixel(template, file, x, y) {
  const source = path.join(TEMPLATES_DIR, template, file);
  const { data, info } = await sharp(source)
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  const at = (y * info.width + x) * 4;
  return [data[at], data[at + 1], data[at + 2]];
}

async function sampleTemplate(card) {
  const out = {};
  for (const [name, [file, x, y]] of Object.entries(card.samples)) {
    out[name] = await samplePixel(card.template, file, x, y);
  }
  return out;
}

function figurePalette(body) {
  return {
    O: INK,
    K: mixColor(body, [255, 255, 255], 0.55),
    E: INK,
    B: body,
    A: scaleColor(body, 0.7)
  };
}

function drawPlatformerCard(canvas, colors) {
  const grass = colors.tile;
  const dirt = scaleColor(colors.tile, 0.55);
  const deep = scaleColor(colors.tile, 0.3);
  const groundTop = 54;
  for (let y = 0; y < groundTop; y++) {
    canvas.row(
      y,
      mixColor(scaleColor(colors.sky, 1.35), colors.sky, y / (groundTop - 1))
    );
  }
  // Grass cap, then dirt falling away to the bottom edge, so the band has depth.
  canvas.fill(0, groundTop, canvas.width, 3, grass);
  for (let y = groundTop + 3; y < canvas.height; y++) {
    canvas.row(
      y,
      mixColor(dirt, deep, (y - groundTop - 3) / (canvas.height - groundTop - 4))
    );
  }

  // Two platforms, the second higher, so the card reads as a jump arc.
  for (const [x, y, width] of [
    [26, 42, 22],
    [74, 28, 20]
  ]) {
    canvas.fill(x, y, width, 3, grass);
    canvas.fill(x, y + 3, width, 5, dirt);
    canvas.fill(x, y, width, 1, INK);
    canvas.fill(x, y + 7, width, 1, deep);
  }

  drawSprite(canvas, FIGURE_LARGE, 10, groundTop - 20, figurePalette(colors.player), 2);
  drawSprite(canvas, FIGURE_SMALL, 78, 18, figurePalette(colors.enemy), 2);

  for (const [x, y] of [
    [52, 34],
    [60, 28],
    [68, 22]
  ]) {
    canvas.fill(x, y, 3, 3, colors.accent);
    canvas.fill(x, y, 3, 1, INK);
  }
}

function drawTopdownCard(canvas, colors) {
  const floorA = scaleColor(colors.floor, 0.85);
  const floorB = scaleColor(colors.floor, 0.68);
  const wall = scaleColor(colors.wall, 0.45);

  for (let y = 0; y < canvas.height; y++) {
    for (let x = 0; x < canvas.width; x++) {
      const checker = (Math.floor(x / 8) + Math.floor(y / 8)) % 2 === 0;
      canvas.set(x, y, checker ? floorA : floorB);
    }
  }

  // Walls on all four sides, with a door gap in the top run.
  canvas.fill(0, 0, canvas.width, 8, wall);
  canvas.fill(0, canvas.height - 8, canvas.width, 8, wall);
  canvas.fill(0, 0, 8, canvas.height, wall);
  canvas.fill(canvas.width - 8, 0, 8, canvas.height, wall);
  canvas.fill(56, 0, 16, 8, scaleColor(colors.floor, 0.3));
  canvas.fill(56, 6, 16, 2, colors.wall);

  // Inner edge line, so the room has depth rather than a flat border.
  canvas.fill(8, 8, canvas.width - 16, 1, INK);
  canvas.fill(8, canvas.height - 9, canvas.width - 16, 1, INK);
  canvas.fill(8, 8, 1, canvas.height - 16, INK);
  canvas.fill(canvas.width - 9, 8, 1, canvas.height - 16, INK);

  drawSprite(canvas, FIGURE_TOPDOWN, 54, 30, figurePalette(colors.player), 3);
  drawSprite(canvas, FIGURE_TOPDOWN, 22, 16, figurePalette(colors.enemy), 2);
  drawSprite(canvas, FIGURE_TOPDOWN, 92, 44, figurePalette(colors.enemy), 2);
}

function drawShmupCard(canvas, colors) {
  const top = scaleColor(colors.sky, 0.55);
  for (let y = 0; y < canvas.height; y++) {
    canvas.row(y, mixColor(top, colors.sky, y / (canvas.height - 1)));
  }

  // Star field: a fixed LCG, so the field is the same on every run.
  let seed = 20240917;
  const star = mixColor(colors.sky, [255, 255, 255], 0.8);
  for (let i = 0; i < 90; i++) {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    const x = seed % canvas.width;
    seed = (seed * 1103515245 + 12345) % 2147483648;
    const y = seed % canvas.height;
    canvas.set(x, y, star);
  }

  for (const x of [24, 56, 88]) {
    drawSprite(canvas, DRONE, x, 10, figurePalette(colors.enemy), 3);
  }
  drawSprite(canvas, SHIP, 50, 44, figurePalette(colors.player), 4);

  // Player fire going up, enemy fire coming down.
  const shot = mixColor(colors.player, [255, 255, 255], 0.4);
  for (const [x, y, height] of [
    [63, 32, 8],
    [63, 20, 5]
  ]) {
    canvas.fill(x, y, 2, height, shot);
  }
  for (const [x, y] of [
    [31, 28],
    [95, 34]
  ]) {
    canvas.fill(x, y, 2, 5, mixColor(colors.enemy, INK, 0.3));
  }
}

// ----------------------------------------------------------------------- main

async function renderAll() {
  const files = [];

  for (const entry of STYLE_TILES) {
    const canvas = drawStyleTile(entry);
    files.push({
      file: path.join(STYLES_DIR, `game-${entry.id}.png`),
      bytes: encodePng(canvas.width, canvas.height, canvas.data)
    });
  }

  for (const card of TEMPLATE_CARDS) {
    const colors = await sampleTemplate(card);
    const canvas = new Canvas(CARD_WIDTH / CARD_SCALE, CARD_HEIGHT / CARD_SCALE);
    card.draw(canvas, colors);
    const scaled = upscale(canvas, CARD_SCALE);
    files.push({
      file: path.join(TEMPLATE_CARD_DIR, `game-${card.template}.png`),
      bytes: encodePng(scaled.width, scaled.height, scaled.data)
    });
  }

  return files;
}

async function main() {
  const check = process.argv.includes("--check");
  const files = await renderAll();

  const expected = STYLE_TILES.length + TEMPLATE_CARDS.length;
  if (files.length !== expected) {
    console.error(`rendered ${files.length} tiles, expected ${expected}`);
    process.exitCode = 1;
    return;
  }

  if (check) {
    const drifted = [];
    for (const { file, bytes } of files) {
      const current = await readFile(file).catch(() => null);
      if (!current?.equals(bytes)) {
        drifted.push(path.relative(ROOT, file));
      }
    }
    if (drifted.length > 0) {
      console.error(
        `${drifted.length} tile(s) differ from the script:\n  ${drifted.join("\n  ")}\n` +
          "Run: node scripts/make-game-style-tiles.mjs"
      );
      process.exitCode = 1;
      return;
    }
    console.log(`${files.length} tiles match the script.`);
    return;
  }

  await mkdir(STYLES_DIR, { recursive: true });
  await mkdir(TEMPLATE_CARD_DIR, { recursive: true });
  for (const { file, bytes } of files) {
    await writeFile(file, bytes);
    console.log(`wrote ${path.relative(ROOT, file)} (${bytes.length} bytes)`);
  }
}

await main();
